// Abbozle · Wordle word lists
// Source: "wordle-words" npm package (MIT, Michael Chan), the original Wordle lists.
// A few words NYT later removed from answers are kept as valid guesses only.
// Words are stored as one string of 5-letter chunks to keep the file small.
(function () {
  const chunk = (s) => s.match(/.{5}/g);
  const ANSWERS = chunk("");
  const EXTRA = chunk("");
  window.WORDS = {
    answers: ANSWERS,
    valid: new Set(ANSWERS.concat(EXTRA)),
  };
})();
